// Oeste EqualizerBars — Huntington theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with arbitrary values, JSX transform.
// Requires Huntington tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/huntington/src/index.js
// Docs: https://oeste.hiddeninwest.com/huntington/#/components/equalizer-bars

export function EqualizerBars({ label }) {
  return (
    <span role="img" aria-label={label || "Playing"} className="inline-flex items-end gap-[3px]">
      <span aria-hidden="true" className="inline-block h-[15px] w-[3px] bg-[var(--color-ink)]" />
      <span aria-hidden="true" className="inline-block h-[15px] w-[3px] bg-[var(--color-ink)]" />
      <span aria-hidden="true" className="inline-block h-[15px] w-[3px] bg-[var(--color-ink)]" />
      <span aria-hidden="true" className="inline-block h-[15px] w-[3px] bg-[var(--color-ink)]" />
    </span>
  );
}
